// Same-origin replay clocks can also be opened in an independent OBS CEF profile
// using the timestamped URL generated by the controller. No video or page UI.
const $=id=>document.getElementById(id), key='tiangong:obs-replay:v1';
const q=new URLSearchParams(location.search), replay=q.get('mode')==='replay';
const gauge=(id,label,unit,maxValue,digits)=>{const g=new MissionTelemetry.Gauge({mountEl:$(id),label,unit,maxValue,fractionDigits:digits});g.setVisible(true,{immediate:true});g.valueNode.textContent='—';return g};
const speed=gauge('speed','SPEED','KM/H',30600,0),height=gauge('height','ALTITUDE','KM',700,1);
const clock=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
let attitude=new Map(),rows,axis,last='';
async function refreshAttitude(){try{const r=await fetch('data/capsule-attitude.json',{cache:'no-cache'});if(!r.ok)return;const d=await r.json();if(d.frame!=='local-horizontal-nose-up'||d.unit!=='deg')return;
 attitude=new Map(d.samples.filter(s=>typeof s.source==='string'&&s.source.startsWith('https://')&&typeof s.at==='string'&&/(Z|[+-]\d\d:\d\d)$/.test(s.at)&&Number.isFinite(Date.parse(s.at))&&Number.isFinite(s.pitchDeg)&&Math.abs(s.pitchDeg)<=90).map(s=>[s.mission+':'+Math.floor(Date.parse(s.at)/1000),s.pitchDeg]));last='';}catch{}}
function orient(at){const p=attitude.get((replay?'SZ12':'SZ23')+':'+Math.floor(at/1000));if(p===undefined)$('capsulePitch').removeAttribute('transform');else $('capsulePitch').setAttribute('transform',`rotate(${90-p} 105 81)`)}
let state={s:0,at:Date.now(),rate:1,run:true,loop:false,m:'A'};
function accept(o){if(!o||!Number.isFinite(o.s)||o.s<0||o.s>3060||!Number.isFinite(o.at)||![1,10,60].includes(o.rate)||!['A','B'].includes(o.m))return;state=o;last=''}
if(replay){try{if(q.has('state'))accept(JSON.parse(q.get('state')));else accept(JSON.parse(localStorage.getItem(key)))}catch{}window.addEventListener('storage',e=>{if(e.key===key)try{accept(JSON.parse(e.newValue))}catch{}})}
$('overlayMissionName').textContent=replay?'北京时间 · 神舟十二号仿真':'北京时间';
$('dot').style.display='none';$('sphere').querySelector('path[stroke-dasharray]').setAttribute('d','');
async function loadReplay(){const res=await fetch('historical/return-profile.csv');if(!res.ok)throw Error('profile');const samples={A:[],B:[]},events=[];for(const line of (await res.text()).trim().split(/\r?\n/).slice(1)){const [at,t,event,,m,h,v,x]=line.split(',');samples[m].push({at:Date.parse(at),h:+h,v:+v,x:+x});if(m==='A'&&event)events.push({time:+t,name:event})}if(Object.values(samples).some(a=>a.length!==3061))throw Error('profile');rows=samples;axis=new MissionTimeline.TimelineRenderer({mountEl:$('timelineMount'),missionDuration:3060});axis.setEvents(events);draw()}
function draw(){const now=Date.now();if(!replay){$('overlayClockTime').textContent=clock.format(now);orient(now);return}if(!rows)return;let i=Math.floor(state.s+Math.max(0,now-state.at)/1000*(state.run?state.rate:0));i=state.loop?i%3061:Math.min(i,3060);const k=state.m+i;if(last===k)return;last=k;const a=rows[state.m],r=a[i];$('overlayClockTime').textContent=clock.format(r.at);orient(r.at);speed.setValue(r.v*3.6);height.setValue(r.h);axis.setCurrentTimeOffset(i);axis.render();const angle=(r.x-a[3060].x/2)/6371, radius=103*(1+r.h/6371);$('dot').style.display='';$('dot').setAttribute('cx',radius*Math.sin(angle));$('dot').setAttribute('cy',-0.28*radius*Math.cos(angle))}
refreshAttitude();if(!replay)setInterval(refreshAttitude,60000);if(replay)loadReplay().catch(()=>{$('overlayClockTime').textContent='—'});draw();setInterval(draw,150);
